          {
            "file": "example.ts",
            "lines": [
              "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">  IdentityVerificationSheetEventsEnum,</span>",
              "<span style=\"color:#E1E4E8\">  StripeIdentity,</span>",
              "<span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe-identity'</span><span style=\"color:#E1E4E8\">;</span>",
              "",
              "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> verificationResultListener</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeIdentity.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  IdentityVerificationSheetEventsEnum.VerificationResult,</span>",
              "<span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">verification</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (verification.result </span><span style=\"color:#F97583\">===</span><span style=\"color:#E1E4E8\"> IdentityVerificationSheetEventsEnum.Completed) {</span>",
              "<span style=\"color:#a0aab5\">      // Documents were submitted. Confirm the outcome with webhooks.</span>",
              "<span style=\"color:#E1E4E8\">    } </span><span style=\"color:#F97583\">else</span><span style=\"color:#F97583\"> if</span><span style=\"color:#E1E4E8\"> (verification.result </span><span style=\"color:#F97583\">===</span><span style=\"color:#E1E4E8\"> IdentityVerificationSheetEventsEnum.Canceled) {</span>",
              "<span style=\"color:#a0aab5\">      // The user dismissed the sheet. Allow them to try again.</span>",
              "<span style=\"color:#E1E4E8\">    } </span><span style=\"color:#F97583\">else</span><span style=\"color:#F97583\"> if</span><span style=\"color:#E1E4E8\"> (verification.result </span><span style=\"color:#F97583\">===</span><span style=\"color:#E1E4E8\"> IdentityVerificationSheetEventsEnum.Failed) {</span>",
              "<span style=\"color:#E1E4E8\">      console.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">(verification.error?.message);</span>",
              "<span style=\"color:#E1E4E8\">    }</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> failedToLoadListener</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeIdentity.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  IdentityVerificationSheetEventsEnum.FailedToLoad,</span>",
              "<span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">error</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#a0aab5\">    // iOS follows StripeIdentityError; Android v8.2.1 currently emits `error`.</span>",
              "<span style=\"color:#F97583\">    const</span><span style=\"color:#79B8FF\"> message</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> error.message </span><span style=\"color:#F97583\">??</span><span style=\"color:#E1E4E8\"> (error </span><span style=\"color:#F97583\">as</span><span style=\"color:#79B8FF\"> unknown</span><span style=\"color:#F97583\"> as</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#FFAB70\">error</span><span style=\"color:#F97583\">?:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\"> }).error;</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">(message);</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeIdentity.</span><span style=\"color:#B392F0\">initialize</span><span style=\"color:#E1E4E8\">({</span>",
              "<span style=\"color:#E1E4E8\">  publishableKey,</span>",
              "<span style=\"color:#E1E4E8\">});</span>",
              "",
              "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> response</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'https://example.com/identify'</span><span style=\"color:#E1E4E8\">, { method: </span><span style=\"color:#9ECBFF\">'POST'</span><span style=\"color:#E1E4E8\"> });</span>",
              "<span style=\"color:#F97583\">const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">verificationId</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">ephemeralKeySecret</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#79B8FF\">clientSecret</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> response.</span><span style=\"color:#B392F0\">json</span><span style=\"color:#E1E4E8\">();</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeIdentity.</span><span style=\"color:#B392F0\">create</span><span style=\"color:#E1E4E8\">({</span>",
              "<span style=\"color:#E1E4E8\">  verificationId,</span>",
              "<span style=\"color:#E1E4E8\">  ephemeralKeySecret,</span>",
              "<span style=\"color:#E1E4E8\">  clientSecret,</span>",
              "<span style=\"color:#E1E4E8\">});</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeIdentity.</span><span style=\"color:#B392F0\">present</span><span style=\"color:#E1E4E8\">();</span>",
              "",
              "<span style=\"color:#a0aab5\">// Keep verificationResultListener and failedToLoadListener until their owner is destroyed.</span>",
              ""
            ]
          }
