              "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { StripeTerminal, TerminalEventsEnum } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe-terminal'</span><span style=\"color:#E1E4E8\">;</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.ReportAvailableUpdate,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">update</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (window.</span><span style=\"color:#B392F0\">confirm</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Will you update the device?'</span><span style=\"color:#E1E4E8\">)) {</span>",
              "<span style=\"color:#F97583\">      await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">installAvailableUpdate</span><span style=\"color:#E1E4E8\">();</span>",
              "<span style=\"color:#E1E4E8\">    }</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.StartInstallingUpdate,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">update</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(update);</span>",
              "<span style=\"color:#F97583\">    if</span><span style=\"color:#E1E4E8\"> (window.</span><span style=\"color:#B392F0\">confirm</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Will you interrupt the update?'</span><span style=\"color:#E1E4E8\">)) {</span>",
              "<span style=\"color:#F97583\">      await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">cancelInstallUpdate</span><span style=\"color:#E1E4E8\">();</span>",
              "<span style=\"color:#E1E4E8\">    }</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.ReaderSoftwareUpdateProgress,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">progress</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(progress);</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.FinishInstallingUpdate,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#FFAB70\">args</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(args);</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
