              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.BatteryLevel,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">level</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">charging</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">status</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
