            "file": "tap-to-pay.ts",
            "lines": [
              "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">  StripeTerminal,</span>",
              "<span style=\"color:#E1E4E8\">  TapToPayDarkMode,</span>",
              "<span style=\"color:#E1E4E8\">  TerminalConnectTypes,</span>",
              "<span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe-terminal'</span><span style=\"color:#E1E4E8\">;</span>",
              "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { Capacitor } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor/core'</span><span style=\"color:#E1E4E8\">;</span>",
              "",
              "<span style=\"color:#a0aab5\">// Register the authenticated RequestedConnectionToken provider first.</span>",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">initialize</span><span style=\"color:#E1E4E8\">({ isTest: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\"> });</span>",
              "",
              "<span style=\"color:#F97583\">if</span><span style=\"color:#E1E4E8\"> (Capacitor.</span><span style=\"color:#B392F0\">getPlatform</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'ios'</span><span style=\"color:#E1E4E8\">) {</span>",
              "<span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">isLinked</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">isTapToPayAccountLinked</span><span style=\"color:#E1E4E8\">();</span>",
              "<span style=\"color:#E1E4E8\">  console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(isLinked);</span>",
              "<span style=\"color:#E1E4E8\">}</span>",
              "",
              "<span style=\"color:#F97583\">if</span><span style=\"color:#E1E4E8\"> (Capacitor.</span><span style=\"color:#B392F0\">getPlatform</span><span style=\"color:#E1E4E8\">() </span><span style=\"color:#F97583\">===</span><span style=\"color:#9ECBFF\"> 'android'</span><span style=\"color:#E1E4E8\">) {</span>",
              "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">setTapToPayUxConfiguration</span><span style=\"color:#E1E4E8\">({</span>",
              "<span style=\"color:#E1E4E8\">    colors: { primary: </span><span style=\"color:#9ECBFF\">'#FF5733'</span><span style=\"color:#E1E4E8\"> },</span>",
              "<span style=\"color:#E1E4E8\">    darkMode: TapToPayDarkMode.Light,</span>",
              "<span style=\"color:#E1E4E8\">  });</span>",
              "<span style=\"color:#E1E4E8\">}</span>",
              "",
              "<span style=\"color:#F97583\">const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">readers</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">discoverReaders</span><span style=\"color:#E1E4E8\">({</span>",
              "<span style=\"color:#E1E4E8\">  type: TerminalConnectTypes.TapToPay,</span>",
              "<span style=\"color:#E1E4E8\">  locationId: </span><span style=\"color:#9ECBFF\">'**************'</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">});</span>",
              "",
              "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> reader</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> readers[</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">];</span>",
              "<span style=\"color:#F97583\">if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">reader) </span><span style=\"color:#F97583\">throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Tap to Pay is not available on this device'</span><span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">connectReader</span><span style=\"color:#E1E4E8\">({</span>",
              "<span style=\"color:#E1E4E8\">  reader,</span>",
              "<span style=\"color:#E1E4E8\">  autoReconnectOnUnexpectedDisconnect: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">});</span>",
              ""
            ]
