              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">setReaderDisplay</span><span style=\"color:#E1E4E8\">({</span>",
              "<span style=\"color:#E1E4E8\">  currency: </span><span style=\"color:#9ECBFF\">'usd'</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">  tax: </span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">  total: </span><span style=\"color:#79B8FF\">1000</span><span style=\"color:#E1E4E8\">,</span>",
