              "<span style=\"color:#E1E4E8\">    {</span>",
              "<span style=\"color:#E1E4E8\">      displayName: </span><span style=\"color:#9ECBFF\">'winecode'</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">      quantity: </span><span style=\"color:#79B8FF\">2</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">      amount: </span><span style=\"color:#79B8FF\">500</span><span style=\"color:#E1E4E8\">,</span>",
              "<span style=\"color:#E1E4E8\">    },</span>",
              "<span style=\"color:#E1E4E8\">  ],</span>",
              "<span style=\"color:#E1E4E8\">});</span>",
