              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">clearReaderDisplay</span><span style=\"color:#E1E4E8\">();</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">cancelDiscoverReaders</span><span style=\"color:#E1E4E8\">();</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.UnexpectedReaderDisconnect,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">reader</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(reader);</span>",
