              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.ReaderReconnectStarted,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">reader</span><span style=\"color:#E1E4E8\">, </span><span style=\"color:#FFAB70\">reason</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(reader, reason);</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.ReaderReconnectSucceeded,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">reader</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(reader);</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.ReaderReconnectFailed,</span>",
              "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> ({ </span><span style=\"color:#FFAB70\">reader</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(reader);</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">cancelReaderReconnection</span><span style=\"color:#E1E4E8\">();</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">rebootReader</span><span style=\"color:#E1E4E8\">();</span>",
              "",
              "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
              "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.Failed,</span>",
              "<span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">info</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
              "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(info.message, info.code, info.declineCode);</span>",
              "<span style=\"color:#E1E4E8\">  },</span>",
              "<span style=\"color:#E1E4E8\">);</span>",
